    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != background]
    if not points:
        return [row[:] for row in grid]
    marker = max({grid[r][c] for r, c in points}, key=lambda v: sum(grid[r][c] == v for r, c in points))
    out = [row[:] for row in grid]

    # Connect horizontal bars identified by three or more same-color points.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == marker]
        if len(cols) >= 3:
            for c in range(min(cols), max(cols) + 1):
                if grid[r][c] == background:
                    out[r][c] = 2
        else:
            for a, b in zip(cols, cols[1:]):
                if b - a == 2 and grid[r][a + 1] == background:
                    out[r][a + 1] = 2

    # Connect longer vertical rails identified by four or more marks; also
    # repair single-cell holes in shorter aligned strokes.
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == marker]
        if len(rows) >= 4:
            for r in range(min(rows), max(rows) + 1):
                if grid[r][c] == background:
                    out[r][c] = 2
        else:
            for a, b in zip(rows, rows[1:]):
                if b - a == 2 and grid[a + 1][c] == background:
                    out[a + 1][c] = 2
    return out

