    marker = max({grid[r][c] for r, c in points},
                 key=lambda value: sum(grid[r][c] == value for r, c in points))
    out = [row[:] for row in grid]
    r0 = min(r for r, c in points)
    r1 = max(r for r, c in points)
    c0 = min(c for r, c in points)
    c1 = max(c for r, c in points)

    # Lines with at least three marker cells are completed between their extremes.
    for r in range(r0, r1 + 1):
        cols = [c for c in range(c0, c1 + 1) if grid[r][c] == marker]
        if len(cols) >= 3:
            for c in range(min(cols), max(cols) + 1):
                if grid[r][c] == background:
                    out[r][c] = 2
    for c in range(c0, c1 + 1):
        rows = [r for r in range(r0, r1 + 1) if grid[r][c] == marker]
        if len(rows) >= 3:
            for r in range(min(rows), max(rows) + 1):
                if grid[r][c] == background:
                    out[r][c] = 2

    # When marks establish all four sides, complete the frame edges too;
    # this covers a side such as the two-point top edge in a sparse example.
    frame = (
        sum(grid[r0][c] == marker for c in range(c0, c1 + 1)) >= 2 and
        sum(grid[r1][c] == marker for c in range(c0, c1 + 1)) >= 2 and
        sum(grid[r][c0] == marker for r in range(r0, r1 + 1)) >= 2 and
        sum(grid[r][c1] == marker for r in range(r0, r1 + 1)) >= 2
    )
    if frame:
        for c in range(c0, c1 + 1):
            if grid[r0][c] == background:
                out[r0][c] = 2
            if grid[r1][c] == background:
                out[r1][c] = 2
        for r in range(r0, r1 + 1):
            if grid[r][c0] == background:
                out[r][c0] = 2
            if grid[r][c1] == background:
                out[r][c1] = 2
    return out

