    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != background]
    out = [row[:] for row in grid]
    if not points:
        return out
    marker = max({grid[r][c] for r, c in points},
                 key=lambda v: sum(grid[r][c] == v for r, c in points))

    # Horizontal strokes are recognized by 3+ markers on a row; vertical
    # strokes by 2+ markers in a column. Bridge between extreme endpoints
    # with color 2 while preserving original marker pixels.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == marker]
        if len(cols) >= 3:
            for c in range(min(cols), max(cols) + 1):
                if grid[r][c] == background:
                    out[r][c] = 2
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == marker]
        if len(rows) >= 2:
            for r in range(min(rows), max(rows) + 1):
                if grid[r][c] == background:
                    out[r][c] = 2
    return out

