                if grid[r][c] == background:
                    out[r][c] = 2

    # For each interior vertical line, fill only intervals bracketed by marker
    # endpoints. Do not connect the distant side-frame markers.
    left_edge = min(c for r, c in points)
    right_edge = max(c for r, c in points)
    for c in range(left_edge + 1, right_edge):
        rows = [r for r in range(top + 1, bottom) if grid[r][c] == marker]
        if len(rows) >= 2:
            for upper, lower in zip(rows, rows[1:]):
